mapper.select:
SELECT pr.*, (e.first_name || ' ' || e.last_name) AS employee_name, e.employee_code, u.display_name AS reviewer_name FROM employee_profile_requests pr INNER JOIN employees e ON e.id = pr.employee_id LEFT JOIN users u ON u.id = pr.reviewer_id WHERE pr.company_id = #{companyId}
AND pr.employee_id = #{employeeId}
AND pr.status = #{status}
ORDER BY pr.id DESC
